def _add_years(d, years):
    if not d or not years:
        return d
    try:
        return d.replace(year=d.year + int(years))
    except ValueError:
        return d.replace(year=d.year + int(years), day=28)


def imposta_durate_corsi(apps, schema_editor):
    CorsoFormazione = apps.get_model('core', 'CorsoFormazione')
    CorsoDipendente = apps.get_model('core', 'CorsoDipendente')
    for ordine, nome, durata_anni in DEFAULT_DURATE:
        corso, created = CorsoFormazione.objects.get_or_create(
            nome=nome,
            defaults={'ordine': ordine, 'durata_anni': durata_anni, 'attivo': True}
        )
        if not created and corso.durata_anni != durata_anni:
            corso.durata_anni = durata_anni
            corso.save(update_fields=['durata_anni'])

    # Per eventuali corsi già segnati come FATTO prima dell'introduzione di data_esecuzione,
    # sposta la data inserita in data_esecuzione e calcola data_scadenza dopo il periodo di validità
    for cd in CorsoDipendente.objects.select_related('corso').filter(stato='FATTO', data_esecuzione__isnull=True, data_scadenza__isnull=False):
        cd.data_esecuzione = cd.data_scadenza
        durata = cd.corso.durata_anni if cd.corso else 5
        cd.data_scadenza = _add_years(cd.data_esecuzione, durata)
        cd.save(update_fields=['data_esecuzione', 'data_scadenza'])


